//@ProcessingGroup("endorsement")
@Component("endorsement-projector")
public class EndorsementProjector extends EndorsementEntityProjector {
		
	// core constructor
	public EndorsementProjector(ProjectorRegistry registry,
									EndorsementRepository repository,
									QueryUpdateEmitter queryUpdateEmitter ) {
        super(registry, repository);
        this.queryUpdateEmitter = queryUpdateEmitter;
    }	

	/*
     * @param	event CreateEndorsementEvent
     */
    @EventHandler( payloadType=CreateEndorsementEvent.class )
    public void handle( CreateEndorsementEvent event) {
	    LOGGER.info("handling CreateEndorsementEvent - " + event );
	    Endorsement entity = new Endorsement();
            entity.setEndorsementId( event.getEndorsementId() );
            entity.setEndorsementNumber( event.getEndorsementNumber() );
            entity.setEffectiveDate( event.getEffectiveDate() );
            entity.setDescription( event.getDescription() );
	    
    	// ------------------------------------------
    	// persist a new one
    	// ------------------------------------------ 
	    create(entity);
        
        // ------------------------------------------
    	// emit to subscribers that find all
    	// ------------------------------------------    	
        emitFindAllEndorsement( entity );
    }

    /*
     * @param	event UpdateEndorsementEvent
     */
    @EventHandler( payloadType=UpdateEndorsementEvent.class )
    public void handle( UpdateEndorsementEvent event) {
    	LOGGER.info("handling UpdateEndorsementEvent - " + event );
    	
	    Endorsement entity = new Endorsement();
            entity.setEndorsementId( event.getEndorsementId() );
            entity.setEndorsementNumber( event.getEndorsementNumber() );
            entity.setEffectiveDate( event.getEffectiveDate() );
            entity.setDescription( event.getDescription() );
            entity.setPolicy( event.getPolicy() );
 
    	// ------------------------------------------
    	// save with an existing instance
    	// ------------------------------------------ 
		update(entity);

    	// ------------------------------------------
    	// emit to subscribers that find one
    	// ------------------------------------------    	
        emitFindEndorsement( entity );

    	// ------------------------------------------
    	// emit to subscribers that find all
    	// ------------------------------------------    	
        emitFindAllEndorsement( entity );        
    }
    
    /*
     * @param	event DeleteEndorsementEvent
     */
    @EventHandler( payloadType=DeleteEndorsementEvent.class )
    public void handle( DeleteEndorsementEvent event) {
    	LOGGER.info("handling DeleteEndorsementEvent - " + event );
    	
    	// ------------------------------------------
    	// delete delegation
    	// ------------------------------------------
    	Endorsement entity = delete( event.getEndorsementId() );

    	// ------------------------------------------
    	// emit to subscribers that find all
    	// ------------------------------------------    	
        emitFindAllEndorsement( entity );

    }    

    /*
     * @param	event AssignPolicyToEndorsementEvent
     */
    @EventHandler( payloadType=AssignPolicyToEndorsementEvent.class)
    public void handle( AssignPolicyToEndorsementEvent event) {
	    LOGGER.info("handling AssignPolicyToEndorsementEvent - " + event );

	    // ------------------------------------------
	    // delegate to assignTo
	    // ------------------------------------------
	    Endorsement entity = assignPolicy( event.getEndorsementId(), event.getAssignment() );

	    // ------------------------------------------
    	// emit to subscribers that find one
    	// ------------------------------------------    	
        emitFindEndorsement( entity );

    	// ------------------------------------------
    	// emit to subscribers that find all
    	// ------------------------------------------    	
        emitFindAllEndorsement( entity );
    }
    

	/*
	 * @param	event UnAssignPolicyFromEndorsementEvent
	 */
	@EventHandler( payloadType=UnAssignPolicyFromEndorsementEvent.class)
	public void handle( UnAssignPolicyFromEndorsementEvent event) {
	    LOGGER.info("handling UnAssignPolicyFromEndorsementEvent - " + event );

	    // ------------------------------------------
	    // delegate to unAssignFrom
	    // ------------------------------------------
	    Endorsement entity = unAssignPolicy( event.getEndorsementId() );

		// ------------------------------------------
		// emit to subscribers that find one
		// ------------------------------------------    	
	    emitFindEndorsement( entity );
	
		// ------------------------------------------
		// emit to subscribers that find all
		// ------------------------------------------    	
	    emitFindAllEndorsement( entity );
	}




    /**
     * Method to retrieve the Endorsement via an EndorsementPrimaryKey.
     * @param 	id Long
     * @return 	Endorsement
     * @exception ProcessingException - Thrown if processing any related problems
     * @exception IllegalArgumentException 
     */
    @SuppressWarnings("unused")
    @QueryHandler
    public Endorsement handle( FindEndorsementQuery query ) 
    throws ProcessingException, IllegalArgumentException {
    	return find( query.getFilter().getEndorsementId() );
    }
    
    /**
     * Method to retrieve a collection of all Endorsements
     *
     * @param	query	FindAllEndorsementQuery 
     * @return 	List<Endorsement> 
     * @exception ProcessingException Thrown if any problems
     */
    @SuppressWarnings("unused")
    @QueryHandler
    public List<Endorsement> handle( FindAllEndorsementQuery query ) throws ProcessingException {
    	return findAll( query );
    }



/**
 * emit to subscription queries of type FindEndorsement,
 * but only if the id matches
 *
 * @param		entity	Endorsement
 */
	protected void emitFindEndorsement( Endorsement entity ) {
		LOGGER.info("handling emitFindEndorsement" );
		
	    queryUpdateEmitter.emit(FindEndorsementQuery.class,
	                            query -> query.getFilter().getEndorsementId().equals(entity.getEndorsementId()),
	                            entity);
	}
	
	/**
	 * unconditionally emit to subscription queries of type FindAllEndorsement
	 * 
	 * @param		entity	Endorsement
	 */
	protected void emitFindAllEndorsement( Endorsement entity ) {
		LOGGER.info("handling emitFindAllEndorsement" );
		
	    queryUpdateEmitter.emit(FindAllEndorsementQuery.class,
	                            query -> true,
	                            entity);
	}

	//--------------------------------------------------
    // attributes
    // --------------------------------------------------
	@Autowired
	private final QueryUpdateEmitter queryUpdateEmitter;
    private static final Logger LOGGER 	= Logger.getLogger(EndorsementProjector.class.getName());

}
